# -*- coding: utf8 -*-

from re             import _pattern_type as regular_expression

from abstract_route import AbstractRoute
from static_route   import StaticRoute

def parse_path(path):
  """
    Converts a path string into a tuple of path components.
  """
  return tuple([component for component in path.split('/') if len(component) > 0])

def make_route(path, name=None, options=None):
  """
    Given a path and an optional name and options, returns a route object.
  """
  if isinstance(path, regular_expression):
    raise NotImplementedError, 'regular expression routes not implemented yet'
  elif ':' in path:
    raise NotImplementedError, 'component routes not implemented yet'
  else:
    return StaticRoute(path, name=name, options=options)

#!/usr/bin/env python
# -*- coding: utf8 -*-

from containers import RouteDict
from errors     import NotFoundError
from routes     import make_route, StaticRoute

class PathMapper(object):
  def __init__(self):
    super(PathMapper, self).__init__()
    self.static_patterns = RouteDict()

  def connect(self, path, name=None, options=None):
    route = make_route(path, name=name, options=options)
    if route.static:
      self.static_patterns.add(route)

  def parse(self, path):
    result = self.static_patterns.match(path)
    if result:
      return result.options
    else:
      raise NotFoundError('%s not found' % path)

#!/usr/bin/env python
# -*- coding: utf8 -*-

import warnings

class RouteDict(dict):
  """
    A hash-table dictionary of Routes. O(1) matching.
  """

  def add(self, route):
    """
      Adds route to the dictionary. If route is already in the dictionary, drops
      the route while issuing a warning.
    """
    for path in route.paths():
      if path in self:
        warnings.warn('Route collision: %s was dropped for %s' % (repr(route), repr(path)))
      else:
        self[path] = route

  def match(self, path):
    """
      Returns the rotue which matches path. Returns False if no route matches.
    """
    return self.get(path, False)

#!/usr/bin/env python
# -*- coding: utf8 -*-

class RouteList(list):
  """
    A simple array of Routes. O(n) matching.
  """

  def add(self, route):
    """
      Appends route to the end of the list.
    """
    self.append(route)

  def match(self, path):
    """
      Returns the first route which matches path. Returns False if no routes
      match. O(n).
    """
    for route in self:
      if route.match(path):
        return route
    return False

